{
  "metadati": {
    "data_sintetica": "2026-04-19",
    "chiave_indagine": null,
    "descrizione": "L’utente segnala una comunicazione intestata al precedente referente {{persona_1}}, che non ricopre più il ruolo, e indica {{email_1}} come recapito. Chiarisce che il problema riguarda il destinatario della comunicazione, non l’accesso, e accetta di sottoporre il cambio del referente all’assistenza."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Abbiamo ricevuto una comunicazione intestata al precedente referente, {{persona_1}}, ma nn ricopre più quel ruolo. Come possiamo segnalare il cambio del referente?"
    },
    {
      "sender": "Agente",
      "testo": "Il problema riguarda solo il destinatario della comunicazione oppure anche l’accesso al servizio? Può segnalare il cambiamento all’assistenza, che valuterà la richiesta."
    },
    {
      "sender": "Utente",
      "testo": "Riguarda solo il destinatario, l’accesso non è un problema. Per eventuali contatti potete usare {{email_1}}."
    },
    {
      "sender": "Agente",
      "testo": "In questo caso sottoponga all’assistenza la segnalazione relativa al cambio del referente e alla comunicazione intestata al precedente referente. L’assistenza verificherà i passaggi applicabili."
    },
    {
      "sender": "Utente",
      "testo": "Va bene, inoltrerò la segnalazione."
    }
  ],
  "trattamento_atteso": {
    "mascherare": [
      {
        "segnaposto": "{{persona_1}}",
        "tipo": "PERSON",
        "sostituzione": "[PERSON_1]"
      },
      {
        "segnaposto": "{{email_1}}",
        "tipo": "EMAIL",
        "sostituzione": "[EMAIL_1]"
      }
    ],
    "conservare": [
      "cambio del referente",
      "comunicazione intestata al precedente referente",
      "Il problema riguarda il destinatario della comunicazione e non l’accesso al servizio."
    ],
    "motivazione": "Il nome del precedente referente e l’indirizzo email offerto dall’utente sono dati personali da mascherare. Restano utili al contesto della richiesta il cambio del referente e il fatto che la comunicazione sia intestata al precedente referente."
  }
}
